{
  "kind": "scattering",
  "schema": {
    "$defs": {
      "ConstantIndex": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex refractive index n + ik.",
        "properties": {
          "kind": {
            "const": "constant_index",
            "default": "constant_index",
            "title": "Kind",
            "type": "string"
          },
          "n_real": {
            "description": "Real part of the refractive index.",
            "title": "N Real",
            "type": "number"
          },
          "n_imag": {
            "default": 0.0,
            "description": "Extinction coefficient k (>= 0 for loss).",
            "minimum": 0,
            "title": "N Imag",
            "type": "number"
          }
        },
        "required": [
          "n_real"
        ],
        "title": "ConstantIndex",
        "type": "object"
      },
      "ConstantPermittivity": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex relative permittivity.",
        "properties": {
          "kind": {
            "const": "constant_permittivity",
            "default": "constant_permittivity",
            "title": "Kind",
            "type": "string"
          },
          "eps_real": {
            "title": "Eps Real",
            "type": "number"
          },
          "eps_imag": {
            "default": 0.0,
            "minimum": 0,
            "title": "Eps Imag",
            "type": "number"
          }
        },
        "required": [
          "eps_real"
        ],
        "title": "ConstantPermittivity",
        "type": "object"
      },
      "Cylinder": {
        "additionalProperties": false,
        "description": "Flat-ended cylinder with axis along z.",
        "properties": {
          "kind": {
            "const": "cylinder",
            "default": "cylinder",
            "title": "Kind",
            "type": "string"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          },
          "length_nm": {
            "exclusiveMinimum": 0,
            "title": "Length Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm",
          "length_nm"
        ],
        "title": "Cylinder",
        "type": "object"
      },
      "Drude": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2 / (w^2 + i*gamma*w), energies in eV.",
        "properties": {
          "kind": {
            "const": "drude",
            "default": "drude",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "description": "Plasma frequency in eV.",
            "exclusiveMinimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping rate in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "wp_ev",
          "gamma_ev"
        ],
        "title": "Drude",
        "type": "object"
      },
      "DrudeLorentz": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2/(w^2 + i g w) + sum_j d_j w0_j^2 / (w0_j^2 - w^2 - i G_j w).\n\nThe form FDTD needs for auxiliary-differential-equation dispersion.\nFit one to measured data with :func:`lightsmith.materials_fit.fit_drude_lorentz`.",
        "properties": {
          "kind": {
            "const": "drude_lorentz",
            "default": "drude_lorentz",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          },
          "poles": {
            "items": {
              "$ref": "#/$defs/LorentzPole"
            },
            "title": "Poles",
            "type": "array"
          }
        },
        "title": "DrudeLorentz",
        "type": "object"
      },
      "FarFieldRequest": {
        "additionalProperties": false,
        "description": "Differential scattering cross section dC_sca/dOmega on a theta x phi grid.\n\ntheta is measured from the incident direction; phi is the azimuth around it,\nmeasured from the incident polarization (phi=0 is the E-plane, 90 the H-plane).",
        "properties": {
          "theta_deg": {
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Theta Deg",
            "type": "array"
          },
          "phi_deg": {
            "default": [
              0.0,
              90.0
            ],
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Phi Deg",
            "type": "array"
          },
          "wavelengths_nm": {
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Wavelengths Nm",
            "type": "array"
          }
        },
        "required": [
          "theta_deg",
          "wavelengths_nm"
        ],
        "title": "FarFieldRequest",
        "type": "object"
      },
      "GaussianBeam": {
        "additionalProperties": false,
        "description": "A focused Gaussian beam: plane waves with the angular spectrum exp(-(k_t w0 / 2)^2), each polarised by\nrotating `polarization` with its direction (aplanatic).\n\nThe angular weights are fixed, so the beam behaves as if focused by a lens of fixed NA: the waist is\n`waist_nm` at `waist_wavelength_nm` (default: the middle of the band) and scales with the wavelength.\nCross sections are normalised by the intensity at the focus.",
        "properties": {
          "kind": {
            "const": "gaussian_beam",
            "default": "gaussian_beam",
            "title": "Kind",
            "type": "string"
          },
          "direction": {
            "default": [
              0.0,
              0.0,
              1.0
            ],
            "description": "Beam axis (propagation).",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Direction",
            "type": "array"
          },
          "polarization": {
            "default": [
              1.0,
              0.0,
              0.0
            ],
            "description": "E-field direction at the axis.",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Polarization",
            "type": "array"
          },
          "waist_nm": {
            "description": "1/e^2 intensity radius at the focus.",
            "exclusiveMinimum": 0,
            "title": "Waist Nm",
            "type": "number"
          },
          "focus_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Focus Nm",
            "type": "array"
          },
          "waist_wavelength_nm": {
            "anyOf": [
              {
                "exclusiveMinimum": 0,
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Vacuum wavelength at which the waist is waist_nm. Default: the middle of the band.",
            "title": "Waist Wavelength Nm"
          }
        },
        "required": [
          "waist_nm"
        ],
        "title": "GaussianBeam",
        "type": "object"
      },
      "LayeredSphere": {
        "additionalProperties": false,
        "description": "Core-shell / multilayer sphere. The particle's `material` is the core;\n`shells` are listed from the inside out.",
        "properties": {
          "kind": {
            "const": "layered_sphere",
            "default": "layered_sphere",
            "title": "Kind",
            "type": "string"
          },
          "core_radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Core Radius Nm",
            "type": "number"
          },
          "shells": {
            "items": {
              "$ref": "#/$defs/Shell"
            },
            "minItems": 1,
            "title": "Shells",
            "type": "array"
          }
        },
        "required": [
          "core_radius_nm",
          "shells"
        ],
        "title": "LayeredSphere",
        "type": "object"
      },
      "LibraryMaterial": {
        "additionalProperties": false,
        "description": "Measured n, k bundled with lightsmith, e.g. ``{\"kind\": \"library\", \"name\": \"Au\",\n\"dataset\": \"Johnson-Christy\"}``. Linear interpolation in n and k, no extrapolation.\n\nNames and datasets accept aliases (\"gold\", \"JC\") and are stored in canonical form;\nan omitted dataset is filled with the material's default so the spec stays\nreproducible. See :func:`list_materials`.",
        "properties": {
          "kind": {
            "const": "library",
            "default": "library",
            "title": "Kind",
            "type": "string"
          },
          "name": {
            "description": "Material, e.g. 'Au', 'Ag', 'Al', 'Cu', 'Si', 'TiO2', 'SiO2', 'H2O'.",
            "title": "Name",
            "type": "string"
          },
          "dataset": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Dataset, e.g. 'Johnson-Christy'; omitted = material default.",
            "title": "Dataset"
          }
        },
        "required": [
          "name"
        ],
        "title": "LibraryMaterial",
        "type": "object"
      },
      "LorentzPole": {
        "additionalProperties": false,
        "properties": {
          "delta_eps": {
            "description": "Oscillator strength (permittivity step).",
            "title": "Delta Eps",
            "type": "number"
          },
          "omega0_ev": {
            "description": "Resonance energy in eV.",
            "exclusiveMinimum": 0,
            "title": "Omega0 Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "delta_eps",
          "omega0_ev",
          "gamma_ev"
        ],
        "title": "LorentzPole",
        "type": "object"
      },
      "NearFieldRequest": {
        "additionalProperties": false,
        "description": "Total electric field on a square plane through the scene.",
        "properties": {
          "plane": {
            "default": "xz",
            "enum": [
              "xy",
              "xz",
              "yz"
            ],
            "title": "Plane",
            "type": "string"
          },
          "offset_nm": {
            "default": 0.0,
            "description": "Position of the plane along its normal.",
            "title": "Offset Nm",
            "type": "number"
          },
          "half_width_nm": {
            "exclusiveMinimum": 0,
            "title": "Half Width Nm",
            "type": "number"
          },
          "points": {
            "default": 101,
            "description": "Samples per axis.",
            "minimum": 2,
            "title": "Points",
            "type": "integer"
          },
          "wavelengths_nm": {
            "description": "Vacuum wavelengths to sample.",
            "items": {
              "type": "number"
            },
            "minItems": 1,
            "title": "Wavelengths Nm",
            "type": "array"
          }
        },
        "required": [
          "half_width_nm",
          "wavelengths_nm"
        ],
        "title": "NearFieldRequest",
        "type": "object"
      },
      "Outputs": {
        "additionalProperties": false,
        "properties": {
          "cross_sections": {
            "default": true,
            "title": "Cross Sections",
            "type": "boolean"
          },
          "near_field": {
            "anyOf": [
              {
                "$ref": "#/$defs/NearFieldRequest"
              },
              {
                "type": "null"
              }
            ],
            "default": null
          },
          "far_field": {
            "anyOf": [
              {
                "$ref": "#/$defs/FarFieldRequest"
              },
              {
                "type": "null"
              }
            ],
            "default": null
          },
          "resonances": {
            "anyOf": [
              {
                "$ref": "#/$defs/ResonanceRequest"
              },
              {
                "type": "null"
              }
            ],
            "default": null
          }
        },
        "title": "Outputs",
        "type": "object"
      },
      "Particle": {
        "additionalProperties": false,
        "properties": {
          "shape": {
            "discriminator": {
              "mapping": {
                "cylinder": "#/$defs/Cylinder",
                "layered_sphere": "#/$defs/LayeredSphere",
                "sphere": "#/$defs/Sphere",
                "spheroid": "#/$defs/Spheroid"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/Sphere"
              },
              {
                "$ref": "#/$defs/Spheroid"
              },
              {
                "$ref": "#/$defs/Cylinder"
              },
              {
                "$ref": "#/$defs/LayeredSphere"
              }
            ],
            "title": "Shape"
          },
          "material": {
            "description": "Particle material (the core for layered spheres).",
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          },
          "position_nm": {
            "default": [
              0.0,
              0.0,
              0.0
            ],
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Position Nm",
            "type": "array"
          }
        },
        "required": [
          "shape",
          "material"
        ],
        "title": "Particle",
        "type": "object"
      },
      "PlaneWave": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "plane_wave",
            "default": "plane_wave",
            "title": "Kind",
            "type": "string"
          },
          "direction": {
            "default": [
              0.0,
              0.0,
              1.0
            ],
            "description": "Propagation direction.",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Direction",
            "type": "array"
          },
          "polarization": {
            "default": [
              1.0,
              0.0,
              0.0
            ],
            "description": "Real E-field direction.",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Polarization",
            "type": "array"
          }
        },
        "title": "PlaneWave",
        "type": "object"
      },
      "ResonanceRequest": {
        "additionalProperties": false,
        "description": "Resonances of the ringing field after the incident pulse has passed: wavelength, Q, relative amplitude.\n\nTime-domain solvers only. Only modes inside the requested wavelength band are reported.",
        "properties": {
          "max_modes": {
            "default": 10,
            "maximum": 100,
            "minimum": 1,
            "title": "Max Modes",
            "type": "integer"
          }
        },
        "title": "ResonanceRequest",
        "type": "object"
      },
      "Shell": {
        "additionalProperties": false,
        "properties": {
          "thickness_nm": {
            "exclusiveMinimum": 0,
            "title": "Thickness Nm",
            "type": "number"
          },
          "material": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          }
        },
        "required": [
          "thickness_nm",
          "material"
        ],
        "title": "Shell",
        "type": "object"
      },
      "Sphere": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "sphere",
            "default": "sphere",
            "title": "Kind",
            "type": "string"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Sphere",
        "type": "object"
      },
      "Spheroid": {
        "additionalProperties": false,
        "description": "Spheroid with symmetry axis along z.",
        "properties": {
          "kind": {
            "const": "spheroid",
            "default": "spheroid",
            "title": "Kind",
            "type": "string"
          },
          "semi_axis_xy_nm": {
            "exclusiveMinimum": 0,
            "title": "Semi Axis Xy Nm",
            "type": "number"
          },
          "semi_axis_z_nm": {
            "exclusiveMinimum": 0,
            "title": "Semi Axis Z Nm",
            "type": "number"
          }
        },
        "required": [
          "semi_axis_xy_nm",
          "semi_axis_z_nm"
        ],
        "title": "Spheroid",
        "type": "object"
      },
      "Substrate": {
        "additionalProperties": false,
        "description": "Semi-infinite half-space z < interface_z_nm with the given material.",
        "properties": {
          "material": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          },
          "interface_z_nm": {
            "default": 0.0,
            "title": "Interface Z Nm",
            "type": "number"
          }
        },
        "required": [
          "material"
        ],
        "title": "Substrate",
        "type": "object"
      },
      "Tabulated": {
        "additionalProperties": false,
        "description": "Tabulated n, k data, linearly interpolated (no extrapolation).",
        "properties": {
          "kind": {
            "const": "tabulated",
            "default": "tabulated",
            "title": "Kind",
            "type": "string"
          },
          "wavelength_nm": {
            "items": {
              "type": "number"
            },
            "title": "Wavelength Nm",
            "type": "array"
          },
          "n_real": {
            "items": {
              "type": "number"
            },
            "title": "N Real",
            "type": "array"
          },
          "n_imag": {
            "items": {
              "type": "number"
            },
            "title": "N Imag",
            "type": "array"
          },
          "source": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Citation / provenance of the data.",
            "title": "Source"
          }
        },
        "required": [
          "wavelength_nm",
          "n_real",
          "n_imag"
        ],
        "title": "Tabulated",
        "type": "object"
      },
      "WavelengthRange": {
        "additionalProperties": false,
        "properties": {
          "start_nm": {
            "exclusiveMinimum": 0,
            "title": "Start Nm",
            "type": "number"
          },
          "stop_nm": {
            "exclusiveMinimum": 0,
            "title": "Stop Nm",
            "type": "number"
          },
          "num": {
            "minimum": 1,
            "title": "Num",
            "type": "integer"
          }
        },
        "required": [
          "start_nm",
          "stop_nm",
          "num"
        ],
        "title": "WavelengthRange",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "description": "A complete scattering problem. Serialisable to/from JSON.",
    "properties": {
      "kind": {
        "const": "scattering",
        "default": "scattering",
        "title": "Kind",
        "type": "string"
      },
      "schema_version": {
        "const": "0.1",
        "default": "0.1",
        "title": "Schema Version",
        "type": "string"
      },
      "particles": {
        "items": {
          "$ref": "#/$defs/Particle"
        },
        "minItems": 1,
        "title": "Particles",
        "type": "array"
      },
      "medium_index": {
        "default": 1.0,
        "description": "Real refractive index of the host medium.",
        "exclusiveMinimum": 0,
        "title": "Medium Index",
        "type": "number"
      },
      "illumination": {
        "anyOf": [
          {
            "$ref": "#/$defs/PlaneWave"
          },
          {
            "$ref": "#/$defs/GaussianBeam"
          }
        ],
        "default": {
          "kind": "plane_wave",
          "direction": [
            0.0,
            0.0,
            1.0
          ],
          "polarization": [
            1.0,
            0.0,
            0.0
          ]
        },
        "title": "Illumination"
      },
      "wavelengths": {
        "anyOf": [
          {
            "items": {
              "type": "number"
            },
            "type": "array"
          },
          {
